static bool IsEven(int n)
{
    return n % 2 == 0;
}
static void Main()
{
    Console.WriteLine(IsEven(7) || IsEven(10));
}

static int Digits(int n)
{
    int c = 0;
    while (n > 0)
    {
        n /= 10;
        c++;
    }
    return c;
}
static void Main()
{
    Console.WriteLine(Digits(90210));
}
